<section class="panel review-section"><div class="panel-head"><div><small>RESPONSÁVEL</small><h3><?=e($responsible['name']??'Não informado')?></h3></div></div><?php if($responsible):?><dl class="detail-grid"><div><dt>CPF</dt><dd><?=e($responsible['cpf'])?></dd></div><div><dt>Cargo</dt><dd><?=e($responsible['position']?:'—')?></dd></div><div><dt>E-mail</dt><dd><?=e($responsible['email'])?></dd></div><div><dt>Telefone</dt><dd><?=e($responsible['phone'])?></dd></div></dl><?php endif;?></section>
