<section class="panel review-section"><div class="panel-head"><div><small>RELACIONAMENTO</small><h3>Pedidos anteriores</h3></div></div><?php if($orders):?><div class="compact-orders"><?php foreach($orders as $order):?><div><strong><?=e($order['code'])?></strong><span><?=e($order['order_type'])?> · <?=e($order['status'])?></span><b>R$ <?=number_format((float)$order['grand_total'],2,',','.')?></b></div><?php endforeach;?></div><?php else:?><p>Nenhum pedido anterior.</p><?php endif;?></section></div>
<aside class="panel admin-decision"><small>DECISÃO</small><h3>Próxima ação</h3><p>Status atual: <strong><?=e($labels[$account['status']]??$account['status'])?></strong></p><?php if($account['status']==='pending'):?><form method="post" action="<?=e(url('/admin/atacadistas/'.$account['id'].'/analise'))?>"><?=csrf_field()?><button class="button button--dark button--block">Iniciar análise</button></form><?php endif;?><?php if(in_array($account['status'],['pending','under_review','rejected'],true)):?><form method="post" action="<?=e(url('/admin/atacadistas/'.$account['id'].'/aprovar'))?>"><?=csrf_field()?><button class="button button--primary button--block">Aprovar cadastro</button></form><?php endif;?><?php if(in_array($account['status'],['pending','under_review'],true)):?><form class="decision-reject" method="post" action="<?=e(url('/admin/atacadistas/'.$account['id'].'/rejeitar'))?>"><?=csrf_field()?><label>Motivo da correção ou rejeição<textarea name="reason" required minlength="10" placeholder="Explique exatamente o que o cliente deve corrigir."></textarea></label><button class="button button--secondary button--block">Solicitar correção</button></form><?php endif;?><?php if($account['status']==='approved'):?><form method="post" action="<?=e(url('/admin/atacadistas/'.$account['id'].'/suspender'))?>"><?=csrf_field()?><label>Motivo da suspensão<textarea name="reason" required minlength="10"></textarea></label><button class="button button--secondary button--block">Suspender acesso</button></form><?php endif;?><?php if($account['status']==='suspended'):?><form method="post" action="<?=e(url('/admin/atacadistas/'.$account['id'].'/reativar'))?>"><?=csrf_field()?><button class="button button--primary button--block">Reativar acesso</button></form><?php endif;?></aside></div>
